#!/usr/bin/env python3
"""GCI India SEO build. Run from the project folder:  python3 build/build.py   (add --offline to skip the database)
Courses come from your Supabase "courses" table (edited in the Admin panel). If the database cannot be reached it falls back to js/data.js.
Reads  build/site.json (domain, name...) + build/template.html
Writes real HTML pages for every public URL (with title, description, canonical, Open Graph,
JSON-LD), plus sitemap.xml, robots.txt, js/meta.js, app.html and 404.html. Needs only Python 3."""
import json, re, os, html, datetime, sys, urllib.request, urllib.parse
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
rd = lambda p: open(os.path.join(ROOT, p), encoding='utf-8').read()
def wr(p, s):
    f = os.path.join(ROOT, p); os.makedirs(os.path.dirname(f), exist_ok=True); open(f, 'w', encoding='utf-8').write(s)
site = json.loads(rd('build/site.json')); URL = site['siteUrl'].rstrip('/')
data = rd('js/data.js')
courses = json.loads(re.search(r'window\.GCI_COURSES\s*=\s*(\[.*?\]);\s*\nwindow\.GCI_FAQ', data, re.S).group(1))
faq = json.loads(re.search(r'window\.GCI_FAQ\s*=\s*(\[.*\]);', data, re.S).group(1))

# ---------- courses from the database (Admin panel) ----------
def slugify(t): return re.sub(r'-+', '-', re.sub(r'[^a-z0-9]+', '-', t.lower())).strip('-')
def iso_of(d):
    m = re.match(r'\s*(\d+)\s*([a-zA-Z])', d or '')
    return 'P' + (m.group(1) if m else '1') + {'d': 'D', 'w': 'W', 'm': 'M', 'y': 'Y'}.get(m.group(2).lower() if m else 'm', 'M')
def from_row(r):
    t = r['title'].strip(); desc = (r.get('description') or '').strip() or t; price = int(r.get('price') or 0)
    st = f'{t} Online in Hindi | GCI India'; st = st if len(st) <= 62 else f'{t} | GCI India'
    sd = f"{desc.rstrip('.')}. Hindi-English video lessons and a certificate. Enroll today."
    learn = r.get('learn') or []; faq_ = r.get('faq') or []
    return dict(id=r['id'], slug=r.get('slug') or slugify(t), t=t, cat=r.get('category') or 'computer', p=price, m=int(r.get('mrp') or 0) or (price * 2 if price else 0),
        d=(r.get('duration') or '').strip() or '1 Month', iso=iso_of(r.get('duration')), r=float(r.get('rating') or 0), n='{:,}'.format(int(r.get('rating_count') or 0)), i=r.get('icon') or 'school',
        tag=(r.get('tag') or '').strip() or ('Free' if not price else 'New'), by=r.get('instructor') or 'GCI India Faculty', thumb=r.get('thumbnail_url') or '',
        seoTitle=(r.get('seo_title') or '').strip() or st, seoDesc=(r.get('seo_desc') or '').strip() or (sd if len(sd) <= 158 else sd[:155].rsplit(' ', 1)[0] + '...'),
        desc=desc, long=(r.get('long_description') or '').strip() or f"{desc.rstrip('.')}. The course is taught in simple Hindi and English with recorded video lessons and practice exercises, and you can claim a GCI India completion certificate after finishing all lessons.",
        learn=learn if len(learn) >= 3 else (learn + ['Practical lessons with real examples', 'Hindi and English explanations', 'A verified completion certificate'])[:max(3, len(learn))],
        faq=faq_ if faq_ else [['Who can join this course?', 'Anyone interested in the topic can join. The lessons start from the basics and are taught in simple Hindi and English.'], ['Will I get a certificate?', 'Yes. After you complete all lessons you can claim a GCI India completion certificate with a roll number that can be verified online.']],
        **({'realRating': True} if r.get('real_rating') else {}))
def fetch_courses():
    cfg = rd('js/config.js'); u = re.search(r"SUPABASE_URL:\s*'([^']*)'", cfg); k = re.search(r"SUPABASE_ANON_KEY:\s*'([^']*)'", cfg)
    if not (u and k and u.group(1) and k.group(1)): print('Database: keys not set in js/config.js -> using js/data.js'); return None
    try:
        req = urllib.request.Request(u.group(1).rstrip('/') + '/rest/v1/courses?select=*&published=eq.true&order=sort_order.asc,id.asc', headers={'apikey': k.group(1), 'Authorization': 'Bearer ' + k.group(1)})
        rows = json.load(urllib.request.urlopen(req, timeout=25))
    except Exception as e: print('Database: could not read courses (' + str(e)[:80] + ') -> using js/data.js'); return None
    if not rows: print('Database: courses table is empty -> using js/data.js'); return None
    print(f'Database: loaded {len(rows)} courses from Supabase'); return [from_row(r) for r in rows]
if '--offline' not in sys.argv:
    _db = fetch_courses()
    if _db:
        courses = _db
        wr('js/data.js', '/* generated by build/build.py from the Supabase "courses" table - edit courses in the Admin panel, not here. */\nwindow.GCI_COURSES = ' + json.dumps(courses, ensure_ascii=False, indent=1) + ';\nwindow.GCI_FAQ = ' + json.dumps(faq, ensure_ascii=False) + ';\n')
about = json.loads(re.search(r'window\.GCI_ABOUT\s*=\s*(\{.*\});', rd('js/about.js'), re.S).group(1))
def fetch_free_notes():
    cfg = rd('js/config.js'); u = re.search(r"SUPABASE_URL:\s*'([^']*)'", cfg); k = re.search(r"SUPABASE_ANON_KEY:\s*'([^']*)'", cfg)
    if '--offline' in sys.argv or not (u and k and u.group(1) and k.group(1)): return []
    try:
        req = urllib.request.Request(u.group(1).rstrip('/') + '/rest/v1/notes?select=title,description,file_path&is_free=eq.true&order=sort_order.asc,id.asc', headers={'apikey': k.group(1), 'Authorization': 'Bearer ' + k.group(1)})
        return [dict(n, url=u.group(1).rstrip('/') + '/storage/v1/object/public/free-notes/' + urllib.parse.quote(n['file_path'])) for n in json.load(urllib.request.urlopen(req, timeout=25))]
    except Exception as e: print('Notes: could not read (' + str(e)[:60] + ')'); return []
free_notes = fetch_free_notes()
tpl = rd('build/template.html'); today = datetime.date.today().isoformat()
E = lambda s: html.escape(str(s), quote=True)
inr = lambda n: '₹{:,}'.format(n)
CATS = {
 'computer': ('Computer Courses Online', 'Computer Courses Online – CCC, O Level, Excel | GCI India', 'Learn CCC, O Level and MS Excel online with Hindi-English lessons, mock tests and certificates. Compare computer courses and enroll today.',
  'Computer skills are required for most office jobs and many government recruitments. Our computer courses cover the CCC exam pattern, the NIELIT O Level IT Tools paper, MS Excel for MIS work and a free beginner course on computer basics and typing. Every course has recorded video lessons in Hindi and English, practice material and a completion certificate.'),
 'web': ('Web Development Courses', 'Web Development Courses Online in Hindi | GCI India', 'Learn HTML, CSS and JavaScript online with real projects and a portfolio. Beginner-friendly web development course in Hindi and English.',
  'Web development is a practical skill that can lead to a job, freelance work or your own business website. Our web development course starts from HTML and CSS, adds JavaScript and Git, and ends with projects that you publish online, so you leave with a portfolio and not only notes.'),
 'marketing': ('Digital Marketing Courses', 'Digital Marketing Courses Online – Free & Paid | GCI India', 'Start with a free digital marketing course, then learn Google Ads and Meta Ads. Practical online lessons in Hindi and English with certificates.',
  'Businesses of every size need customers online. Begin with our free digital marketing starter course to understand SEO, social media and lead generation, then move to the Google Ads and Meta Ads course to learn paid campaigns, tracking and remarketing.'),
 'ecommerce': ('E-commerce Courses', 'Amazon, Flipkart & Meesho Courses – E-commerce | GCI India', 'Learn to sell online in India: Amazon, Flipkart and Meesho seller accounts, GST basics, listings, ads and returns. Step-by-step Hindi course.',
  'Online marketplaces give small sellers access to customers across India, but every platform has its own rules. Our e-commerce course explains seller registration, catalogue creation, pricing, shipping, returns and advertising on Amazon, Flipkart and Meesho in simple Hindi and English.')}
WRAP = 'max-w-7xl mx-auto px-4 py-10'
def card(c):
    price = '<b class="text-t">Free</b>' if not c['p'] else f"<b>{inr(c['p'])}</b> <s class=\"text-slate-500 text-sm\">{inr(c['m'])}</s>"
    return f'<li class="card p-4"><a href="/course/{c["slug"]}/" class="font-bold text-lg hover:text-p">{E(c["t"])}</a><p class="text-sm text-ov mt-1">{E(c["desc"])}</p><p class="text-xs text-ov mt-2">{E(c["d"])} · {E(c["by"])}</p><p class="mt-2">{price}</p></li>'
def grid(cs): return '<ul class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-6">' + ''.join(card(c) for c in cs) + '</ul>'
def faqs(items): return ''.join(f'<details class="border-b border-slate-300 py-3" open><summary class="font-bold">{E(q)}</summary><p class="text-ov text-sm mt-2">{E(a)}</p></details>' for q, a in items)
def band(h1, sub, extra=''): return f'<section class="bg-gradient-to-r from-[#1e3a8a] to-p text-white"><div class="max-w-7xl mx-auto px-4 py-14"><h1 class="text-3xl md:text-4xl font-extrabold max-w-3xl">{E(h1)}</h1><p class="mt-3 max-w-2xl text-blue-100">{E(sub)}</p>{extra}</div></section>'
def catlinks(): return '<nav aria-label="Course categories" class="flex flex-wrap gap-3 mt-6">' + ''.join(f'<a class="btn bo" href="/courses/{k}/">{E(v[0])}</a>' for k, v in CATS.items()) + '<a class="btn bo" href="/free-courses/">Free Courses</a></nav>'
def ld_bc(items): return {"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": i + 1, "name": n, "item": URL + p} for i, (n, p) in enumerate(items)]}
def ld_list(cs): return {"@context": "https://schema.org", "@type": "ItemList", "itemListElement": [{"@type": "ListItem", "position": i + 1, "url": f"{URL}/course/{c['slug']}/", "name": c['t']} for i, c in enumerate(cs)]}
def ld_faq(items): return {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in items]}
org = {"@context": "https://schema.org", "@type": "EducationalOrganization", "name": site['name'], "alternateName": site['legalName'], "url": URL + '/', "logo": URL + site['logo'], "telephone": site['phone'], "sameAs": site['sameAs']}
if site.get('email'): org['email'] = site['email']
if site.get('address'): org['address'] = dict(site['address'], **{"@type": "PostalAddress"})
website = {"@context": "https://schema.org", "@type": "WebSite", "name": site['name'], "url": URL + '/', "inLanguage": "en-IN", "potentialAction": {"@type": "SearchAction", "target": {"@type": "EntryPoint", "urlTemplate": URL + "/courses/?q={search_term_string}"}, "query-input": "required name=search_term_string"}}
def ld_course(c):
    d = {"@context": "https://schema.org", "@type": "Course", "name": c['t'], "description": c['long'], "url": f"{URL}/course/{c['slug']}/", "inLanguage": ["hi", "en"], "timeRequired": c['iso'],
         "provider": {"@type": "EducationalOrganization", "name": site['name'], "url": URL + '/'},
         "offers": {"@type": "Offer", "price": str(c['p']), "priceCurrency": "INR", "availability": "https://schema.org/InStock", "url": f"{URL}/course/{c['slug']}/", "category": "Paid" if c['p'] else "Free"},
         "hasCourseInstance": {"@type": "CourseInstance", "courseMode": "online", "courseWorkload": c['iso']}}
    if c.get('realRating'): d['aggregateRating'] = {"@type": "AggregateRating", "ratingValue": str(c['r']), "ratingCount": c['n'].replace(',', '')}  # only for GENUINE reviews
    return d
pages = []
def add(path, title, desc, body, ld=(), pri='0.6', freq='monthly'): pages.append(dict(path=path, title=title, desc=desc, body=body, ld=list(ld), pri=pri, freq=freq))
free = [c for c in courses if not c['p']]
add('/', 'GCI India – Online CCC, Excel, Web & Marketing Courses', 'Learn CCC, O Level, MS Excel, web development, digital marketing and e-commerce online in Hindi and English. Practical lessons, mock tests and certificates.',
    band('Learn computer, web, marketing and e-commerce skills online in Hindi & English', 'GCI India offers practical, job-focused online courses with recorded video lessons, practice material and a certificate you can verify online.', '<div class="flex flex-wrap gap-3 mt-6"><a href="/courses/" class="btn bd">Explore all courses</a><a href="/free-courses/" class="btn bo" style="background:#fff">Start free</a></div>') +
    f'<section class="{WRAP}"><h2 class="text-2xl font-extrabold">Popular online courses</h2>{grid(courses)}<h2 class="text-2xl font-extrabold mt-12">Browse by category</h2>{catlinks()}<h2 class="text-2xl font-extrabold mt-12">Why learn with GCI India?</h2><p class="mt-3 text-ov max-w-3xl">Lessons are taught in simple Hindi with English technical terms, so you can learn comfortably. Each course is practical, with exercises and real examples, and you can claim a completion certificate that employers can verify with a roll number.</p><h2 class="text-2xl font-extrabold mt-12">Frequently asked questions</h2>{faqs(faq)}</section>',
    [org, website, ld_faq(faq)], '1.0', 'weekly')
add('/courses/', 'All Online Courses – Computer, Web & Marketing | GCI India', 'Browse all GCI India online courses: CCC, O Level, MS Excel, web development, digital marketing and e-commerce. Hindi and English lessons with certificates.',
    band('All Online Courses', 'Career-oriented computer, marketing, e-commerce and web development courses.') + f'<section class="{WRAP}">{catlinks()}{grid(courses)}</section>', [ld_bc([('Home', '/'), ('Courses', '/courses/')]), ld_list(courses)], '0.9', 'weekly')
add('/free-courses/', 'Free Online Courses in Hindi with Certificate | GCI India', 'Start learning free: computer basics and typing, plus a digital marketing starter course. Enroll free and earn a completion certificate.',
    band('Free Online Courses', 'No payment needed. Create a free account, enroll and start learning today.') + f'<section class="{WRAP}">{grid(free)}</section>', [ld_bc([('Home', '/'), ('Free courses', '/free-courses/')]), ld_list(free)], '0.8', 'weekly')
for k, (h1, t, d, intro) in CATS.items():
    cs = [c for c in courses if c['cat'] == k]
    add(f'/courses/{k}/', t, d, band(h1, intro) + f'<section class="{WRAP}">{grid(cs)}{catlinks()}</section>', [ld_bc([('Home', '/'), ('Courses', '/courses/'), (h1, f'/courses/{k}/')]), ld_list(cs)], '0.8', 'weekly')
for c in courses:
    rel = [x for x in courses if x['cat'] == c['cat'] and x['id'] != c['id']] or [x for x in courses if x['id'] != c['id']][:2]
    price = 'Free' if not c['p'] else inr(c['p'])
    body = (band(c['t'], c['desc'], f'<p class="mt-4 text-sm text-blue-100">Created by {E(c["by"])} · {E(c["d"])} · Hindi & English · {price}</p>') +
        f'<section class="{WRAP}"><div class="max-w-3xl"><h2 class="text-xl font-extrabold">About this course</h2><p class="mt-3 leading-relaxed">{E(c["long"])}</p><h2 class="text-xl font-extrabold mt-8">What you will learn</h2><ul class="mt-3 list-disc pl-5 space-y-1">' + ''.join(f'<li>{E(x)}</li>' for x in c['learn']) +
        f'</ul><h2 class="text-xl font-extrabold mt-8">Frequently asked questions</h2>{faqs(c["faq"])}<p class="mt-8"><a href="/signup" class="btn bp">{"Enroll for free" if not c["p"] else "Enroll now – " + price}</a></p></div><h2 class="text-xl font-extrabold mt-12">Related courses</h2>{grid(rel)}</section>')
    add(f'/course/{c["slug"]}/', c['seoTitle'], c['seoDesc'], body, [ld_bc([('Home', '/'), ('Courses', '/courses/'), (c['t'], f'/course/{c["slug"]}/')]), ld_course(c), ld_faq(c['faq'])], '0.9', 'monthly')
def static(path, title, desc, h1, text, cta=None, pri='0.4'):
    add(path, title, desc, band(h1, text) + (f'<section class="{WRAP}">{cta}</section>' if cta else ''), [ld_bc([('Home', '/'), (h1, path)])], pri, 'yearly')
static('/contact-us/', 'Contact GCI India – WhatsApp & Support', 'Contact GCI India for course help, admissions and certificate queries. Chat on WhatsApp Mon–Sat, 9 AM to 7 PM IST.', 'Contact Us', 'Questions about a course, your account or a certificate? Our helpdesk is on WhatsApp Monday to Saturday, 9 AM to 7 PM IST.', f'<a href="https://wa.me/{re.sub(chr(92)+"D","",site["phone"])}" class="btn bp">Chat on WhatsApp</a>', '0.5')
static('/verify-certificate/', 'Verify a GCI India Certificate Online', 'Check whether a GCI India certificate is genuine by entering its roll number. Instant online verification for employers and students.', 'Verify a Certificate', 'Enter the roll number printed on a GCI India certificate to check that it is genuine. JavaScript is required for the verification form.', None, '0.5')

# ---- About, Live classes and Notes pages (rich content) ----
_sec = lambda inner, cls='': f'<section class="{WRAP} {cls}">{inner}</section>'
about_body = (band('About GCI India', about['tagline'], '<div class="flex flex-wrap gap-3 mt-6"><a href="/courses/" class="btn bd">Explore courses</a><a href="/free-courses/" class="btn bo" style="background:#fff">Start free</a></div>') +
    _sec('<h2 class="text-2xl font-extrabold">Who we are</h2>' + ''.join(f'<p class="mt-3 leading-relaxed max-w-3xl">{E(p)}</p>' for p in about['intro']) + f'<h2 class="text-2xl font-extrabold mt-10">Our mission</h2><p class="mt-3 leading-relaxed max-w-3xl">{E(about["mission"])}</p>') +
    _sec('<h2 class="text-2xl font-extrabold">What makes us different</h2><ul class="grid sm:grid-cols-2 gap-4 mt-5">' + ''.join(f'<li class="card p-5"><h3 class="font-bold">{E(v[1])}</h3><p class="text-sm text-ov mt-1">{E(v[2])}</p></li>' for v in about['values']) + '</ul>') +
    _sec('<h2 class="text-2xl font-extrabold">How learning works</h2><ol class="mt-5 space-y-4 list-decimal pl-6 max-w-3xl">' + ''.join(f'<li><b>{E(s[0])}</b><p class="text-sm text-ov">{E(s[1])}</p></li>' for s in about['steps']) + '</ol>') +
    (_sec('<h2 class="text-2xl font-extrabold">Our team</h2><ul class="grid sm:grid-cols-3 gap-4 mt-5">' + ''.join(f'<li class="card p-5"><b>{E(t["name"])}</b><div class="text-sm text-ov">{E(t.get("role", ""))}</div><p class="text-sm mt-2">{E(t.get("bio", ""))}</p></li>' for t in about.get('team', []) if t.get('name')) + '</ul>') if any(t.get('name') for t in about.get('team', [])) else '') +
    _sec(f'<h2 class="text-2xl font-extrabold">Contact</h2><p class="mt-3">{E(about.get("hours", ""))}</p>' + (f'<p class="mt-1">Email: {E(about["email"])}</p>' if about.get('email') else '') + (f'<p class="mt-1">{E(about["address"])}</p>' if about.get('address') else '') + '<p class="mt-4"><a href="/contact-us/" class="btn bp">Contact us</a></p>'))
add('/about-us/', 'About GCI India – Global Computer Institute', 'GCI India (Global Computer Institute) offers practical online computer, web, marketing and e-commerce courses in Hindi and English.', about_body,
    [ld_bc([('Home', '/'), ('About us', '/about-us/')]), {"@context": "https://schema.org", "@type": "AboutPage", "name": "About GCI India", "url": URL + "/about-us/", "mainEntity": {"@type": "EducationalOrganization", "name": site['name'], "url": URL + "/"}}], '0.6', 'yearly')
live_body = (band('Free Live Classes', 'Join our mentors for doubt-clearing and revision sessions, ask your questions live and learn with other students.') +
    _sec('<h2 class="text-xl font-extrabold">How live classes work</h2><ol class="mt-4 space-y-3 list-decimal pl-6 max-w-3xl"><li>Create a free student account.</li><li>Pick an upcoming class and click <b>Register free</b>.</li><li>Fifteen minutes before the class, a <b>Join now</b> button appears on this page.</li><li>After the class, registered students can watch the recording.</li></ol><p class="mt-6 text-ov">The schedule is shown on this page. Enable JavaScript to see the upcoming classes and to register.</p><p class="mt-4"><a href="/signup" class="btn bp">Create free account</a></p>'))
add('/live-classes/', 'Free Live Classes & Doubt Sessions | GCI India', 'Join free live doubt-clearing and revision sessions with GCI India mentors for CCC, Excel and more. Register for the next class.', live_body, [ld_bc([('Home', '/'), ('Live classes', '/live-classes/')])], '0.6', 'weekly')
notes_list = ('<ul class="grid md:grid-cols-2 gap-3 mt-4">' + ''.join(f'<li class="card p-4"><a class="font-bold hover:text-p" href="{E(n["url"])}" rel="noopener">{E(n["title"])}</a><p class="text-sm text-ov mt-1">{E(n.get("description", ""))}</p><p class="text-xs text-ov mt-1">PDF</p></li>' for n in free_notes) + '</ul>') if free_notes else '<p class="mt-3 text-ov">Free notes are added regularly. Course notes and worksheets are available inside each course after you enroll.</p>'
add('/notes-and-pdfs/', 'Study Notes & PDFs for Computer Courses | GCI India', 'Free study notes and PDFs for computer, Excel and digital marketing learners, plus course notes for enrolled GCI India students.', band('Notes & PDFs', 'Free study material for everyone, and course notes for enrolled students.') + _sec('<h2 class="text-xl font-extrabold">Free notes</h2>' + notes_list + '<p class="mt-8"><a href="/courses/" class="btn bp">Browse courses</a></p>'), [ld_bc([('Home', '/'), ('Notes & PDFs', '/notes-and-pdfs/')])], '0.6', 'weekly')

# ---------- head + files ----------
def head(p):
    u = URL + p['path']; img = URL + site['ogImage']; t = E(p['title']); d = E(p['desc'])
    h = [f'<title>{t}</title>', f'<meta name="description" content="{d}">', f'<link rel="canonical" href="{u}">', '<meta name="robots" content="index,follow,max-image-preview:large">',
         f'<link rel="alternate" hreflang="en-IN" href="{u}"><link rel="alternate" hreflang="x-default" href="{u}">',
         f'<meta property="og:type" content="website"><meta property="og:site_name" content="{E(site["name"])}"><meta property="og:locale" content="en_IN"><meta property="og:title" content="{t}"><meta property="og:description" content="{d}"><meta property="og:url" content="{u}"><meta property="og:image" content="{img}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="{E(site["name"])} online courses">',
         f'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{t}"><meta name="twitter:description" content="{d}"><meta name="twitter:image" content="{img}">']
    if site['googleSiteVerification']: h.append(f'<meta name="google-site-verification" content="{E(site["googleSiteVerification"])}">')
    if site['bingSiteVerification']: h.append(f'<meta name="msvalidate.01" content="{E(site["bingSiteVerification"])}">')
    for j in p['ld']: h.append('<script type="application/ld+json">' + json.dumps(j, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/') + '</script>')
    if site['ga4MeasurementId']: g = site['ga4MeasurementId']; h.append(f'<script async src="https://www.googletagmanager.com/gtag/js?id={g}"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag("js",new Date());gtag("config","{g}")</script>')
    return '\n'.join(h)
def out(path): return 'index.html' if path == '/' else path.strip('/') + '/index.html'
for p in pages: wr(out(p['path']), tpl.replace('<!--HEAD-->', head(p)).replace('<!--CONTENT-->', p['body'] + '<noscript><p class="px-4 py-6">Please enable JavaScript to enroll, log in and watch lessons.</p></noscript>'))
import shutil
_cd = os.path.join(ROOT, 'course')
for _d in (os.listdir(_cd) if os.path.isdir(_cd) else []):
    if _d not in {c['slug'] for c in courses} and os.path.isfile(os.path.join(_cd, _d, 'index.html')): shutil.rmtree(os.path.join(_cd, _d))
shell = lambda t, extra: tpl.replace('<!--HEAD-->', f'<title>{t}</title><meta name="robots" content="noindex,nofollow">').replace('<!--CONTENT-->', extra)
wr('app.html', shell('GCI India', ''))
wr('404.html', shell('Page not found | GCI India', f'<section class="max-w-2xl mx-auto px-4 py-20 text-center"><h1 class="text-3xl font-extrabold">Page not found</h1><p class="mt-3 text-ov">The page you are looking for does not exist.</p><p class="mt-6"><a class="btn bd" href="/">Go to home</a> <a class="btn bo" href="/courses/">Browse courses</a></p></section>'))
meta = {p['path']: {'t': p['title'], 'd': p['desc']} for p in pages}
wr('js/meta.js', '/* generated by build/build.py – do not edit */\nwindow.GCI_SITE = ' + json.dumps({'url': URL, 'name': site['name']}) + ';\nwindow.GCI_META = ' + json.dumps(meta, ensure_ascii=False, indent=0) + ';\n')
wr('sitemap.xml', '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + ''.join(f'<url><loc>{URL}{p["path"]}</loc><lastmod>{today}</lastmod><changefreq>{p["freq"]}</changefreq><priority>{p["pri"]}</priority></url>\n' for p in pages) + '</urlset>\n')
wr('robots.txt', 'User-agent: *\nAllow: /\n' + ''.join(f'Disallow: /{x}\n' for x in ['admin', 'dashboard', 'profile', 'learn/', 'certificate/', 'cart', 'login', 'signup', 'forgot', 'reset', 'complete']) + f'\nSitemap: {URL}/sitemap.xml\n')
print(f'Built {len(pages)} pages + app.html, 404.html, sitemap.xml, robots.txt, js/meta.js')
if 'YOUR-DOMAIN' in URL: print('WARNING: set "siteUrl" in build/site.json to your real domain (https://...), then run this script again.')
